const [header, payload, signature] = pm.collectionVariables.get("playerToken").split(".");
let b64 = payload.replace(/-/g, "+").replace(/_/g, "/");
while (b64.length % 4) b64 += "=";
const claims = JSON.parse(atob(b64));
claims.role = "ADMIN";
const forged = btoa(JSON.stringify(claims)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
pm.collectionVariables.set("tamperedToken", header + "." + forged + "." + signature);

